import React, { useContext } from 'react';
import { booleanContext } from '../Context';
import { useStompClient } from 'react-stomp-hooks';

function Logout() {
    const{isLoggedIn, setIsLoggedIn} =useContext(booleanContext )
    const stompClient = useStompClient();
if(stompClient){
  stompClient.deactivate("/app/user.disconnectUser",
        {},
        JSON.stringify({firstName: localStorage.getItem("email"), status:'OFFLINE'})
        )   
}
    setIsLoggedIn(false)
    localStorage.clear();
      return (
          <>
        <div>You Have Successfuly been logged out</div>
        <a href='/'>Return Home</a>
        </>
      )
}

export default Logout;
